import{z as s,x as l,o as A,c as d,q as n,j as r,D as a,d as t,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"数据质量监控","description":"","frontmatter":{"title":"数据质量监控","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/de-quality-monitoring.md","filePath":"quant/de-quality-monitoring.md","lastUpdated":1791063341000}'),F={name:"quant/de-quality-monitoring.md"};function u(D,E,C,p,m,h){const B=l("Mermaid");return A(),d("div",null,[E[2]||(E[2]=n('<h1 id="数据质量监控" tabindex="-1">数据质量监控 <a class="header-anchor" href="#数据质量监控" aria-label="Permalink to &quot;数据质量监控&quot;">​</a></h1><div class="epigraph"><p>数据质量不是「准确」一个维度，而是消费者在一组维度上的满意；没有声明谁在什么用途下消费，质检就没有判据。</p><footer>—— 据 Wang and Strong, Beyond Accuracy: What Data Quality Means to Data Consumers, JMIS, 1996 整理</footer></div><p><a href="/quant/de-backtest-perf">上一课</a>让流水线快了起来；快而脏是更危险的组合——坏数据以更快的速度流进更多实验。本课在入库与消费之间装监控：不问「有没有数据」，问「数据是否配得上它的用途」。一次性审计的口径在<a href="/quant/data-acquisition-audit">数据获取与审计</a>立过五项，本课把它变成常开的断言，与<a href="/quant/alt-data-quality">数据质量体系</a>的另类数据口径并轨。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>质量退化是静默的，因为三种最贵的坏都不报错。字段悄悄变义：供应商改了字段定义或单位，值域看起来正常，口径已换；管道悄悄退化：某只标的的日终文件晚到三小时，晚到率从千分之一涨到百分之五，没人订阅这个数；对账悄悄漂移：第二来源与主源的差逐月增大，单日看都在容差内。更根本的问题是阈值：太松，退化数月才发现；太紧，天天误报，团队把告警渠道静音——静音的监控比没有更糟，因为它给出「有监控」的错觉。</p><p><span class="marginnote">术语翻译：滚动基线就是拿这张表自己过去一段时间的分布当参照系。比如缺失率阈值不写死 5%，而写成「超过过去 60 个交易日均值加 3 倍标准差」——若某字段常态缺失率本就是 8%，绝对阈值会天天报假警，相对基线则只在真正恶化时响。</span></p><h3 id="断言分四层-处置分三档" tabindex="-1">断言分四层，处置分三档 <a class="header-anchor" href="#断言分四层-处置分三档" aria-label="Permalink to &quot;断言分四层，处置分三档&quot;">​</a></h3><p>断言自下而上四层。<strong>模式层</strong>：schema、类型、非空、键唯一，坏即阻断入库。<strong>分布层</strong>：缺失率、异常值率、值域对滚动基线的偏离，超带即标记并告警。<strong>业务层</strong>：复权因子连续性、收益率跳变与停牌对账、成交量为零天数、财报值与公告对账——业务层断言是量化团队独有的护城河，通用数据平台不会替你写。<strong>时效层</strong>：数据到达时间对 SLA 的达成率，分数据源统计。处置三档：阻断（不可入库）、标记（入库带 flag，下游可查）、告警（事后修）。每张核心表一张契约，写明四层断言与阈值。</p><p><span class="marginnote">对账不必买第二套全库：抽二十只股票、若干关键日，与第二来源比价格、股本与成分。系统性差异超过一个 tick 或一股时，先怀疑实体键映射，再怀疑值本身——键错一档，值全错。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>落地四条。<strong>一，契约先行</strong>：每张表入库前写契约（四层断言、阈值、处置档位），契约版本随数据版本钉进实验引用。<strong>二，基线滚动</strong>：分布层阈值相对滚动基线（如过去六十个交易日）计算，不写绝对数——市场自身的季节性会让绝对阈值失灵。<strong>三，告警分级路由</strong>：阻断类进值班，标记类进日报，漂移类进周报；误报率本身入监控，连续误报的断言要么修阈值要么下线。<strong>四，变更联动</strong>：供应商升级、规则修订、引擎替换触发断言全量重跑与影子对比——新旧管道并行喂一段，差异分布超带即停，与<a href="/quant/fml-feature-store-deep">特征存储的深入</a>的双跑一致。</p><p><span class="marginnote">直觉类比：处置三档像进口食品监管——阻断是海关直接扣货不许入境（模式坏 = 毒性不可逆）；标记是贴上检验标签放行、下游自己看标签决定用不用（分布超带可能只是市场极端日，货本身没坏）；告警是先上架、事后召回（迟到问题可补救）。档位分的是「错了能不能撤回」，不是「错得严不严重」。</span></p>',12)),(A(),r(i,null,{default:a(()=>[o(B,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%85%A5%E5%BA%93%E6%B5%81%22%5D%20--%3E%20A1%7B%22%E6%A8%A1%E5%BC%8F%E6%96%AD%E8%A8%80%EF%BC%9Aschema%20%E4%B8%8E%E9%94%AE%22%7D%0A%20%20A1%20--%3E%7C%E5%9D%8F%7C%20BLK%5B%22%E9%98%BB%E6%96%AD%EF%BC%9A%E4%B8%8D%E5%85%A5%E5%BA%93%22%5D%0A%20%20A1%20--%3E%7C%E5%A5%BD%7C%20A2%7B%22%E5%88%86%E5%B8%83%E6%96%AD%E8%A8%80%EF%BC%9A%E5%AF%B9%E6%BB%9A%E5%8A%A8%E5%9F%BA%E7%BA%BF%22%7D%0A%20%20A2%20--%3E%7C%E8%B6%85%E5%B8%A6%7C%20FLAG%5B%22%E6%A0%87%E8%AE%B0%EF%BC%9A%E5%B8%A6%20flag%20%E5%85%A5%E5%BA%93%20%2B%20%E5%91%8A%E8%AD%A6%22%5D%0A%20%20A2%20--%3E%7C%E5%B8%A6%E5%86%85%7C%20A3%7B%22%E4%B8%9A%E5%8A%A1%E6%96%AD%E8%A8%80%EF%BC%9A%E5%A4%8D%E6%9D%83%E3%80%81%E8%B7%B3%E5%8F%98%E3%80%81%E5%AF%B9%E8%B4%A6%22%7D%0A%20%20A3%20--%3E%7C%E5%8F%AF%E7%96%91%7C%20FLAG%0A%20%20A3%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20A4%7B%22%E6%97%B6%E6%95%88%E6%96%AD%E8%A8%80%EF%BC%9ASLA%22%7D%0A%20%20A4%20--%3E%7C%E8%BF%9F%E5%88%B0%7C%20ALM%5B%22%E5%91%8A%E8%AD%A6%EF%BC%9A%E5%88%86%E6%BA%90%E7%BB%9F%E8%AE%A1%22%5D%0A%20%20A4%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20OK%5B%22%E5%B9%B2%E5%87%80%E5%85%A5%E5%BA%93%22%5D%0A%20%20CHG%5B%22%E5%8F%98%E6%9B%B4%EF%BC%9A%E4%BE%9B%E5%BA%94%E5%95%86%20%2F%20%E8%A7%84%E5%88%99%20%2F%20%E5%BC%95%E6%93%8E%22%5D%20--%3E%20SHADOW%5B%22%E5%BD%B1%E5%AD%90%E5%AF%B9%E6%AF%94%EF%BC%9A%E6%96%B0%E6%97%A7%E7%AE%A1%E9%81%93%E5%B9%B6%E8%A1%8C%22%5D%0A%20%20SHADOW%20--%3E%7C%E5%B7%AE%E5%BC%82%E8%B6%85%E5%B8%A6%7C%20BLK%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"监控之所以必须是常开的断言而非定期抽查，在于质量退化的分布是重尾的：一年里绝大多数日子无事，问题集中在供应商升级日、公司行动密集期与市场压力日。定期抽查的发现时间以月计，常开断言把发现压到当次批次。处置分档对应错误的可逆性：模式错是不可逆污染，宁可阻断；分布超带可能只是市场极端日，标记保数据、告警保知情。业务层断言的机制地位最特殊：它是把研究知识前移到数据层的通道——回测里发现的「除息季节性」病灶，下次以断言形式在入库时被拦住，知识不再只活在研究员脑子里。这是本课程反复出现的循环：清洗、复权、版本化、性能，每课的教训最终都沉淀为一条断言。",-1)),(A(),r(i,null,{default:a(()=>[o(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRIG%5B%22%E6%96%AD%E8%A8%80%E8%A7%A6%E5%8F%91%22%5D%20--%3E%20ALM%5B%22%E5%8F%91%E4%B8%80%E6%9D%A1%E5%91%8A%E8%AD%A6%22%5D%0A%20%20ALM%20--%3E%20Q1%7B%22%E6%98%AF%E7%9C%9F%E9%97%AE%E9%A2%98%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%E5%90%A6%EF%BC%9A%E9%98%88%E5%80%BC%E5%A4%AA%E7%B4%A7%7C%20FALSE%5B%22%E8%BF%9E%E7%BB%AD%E8%AF%AF%E6%8A%A5%22%5D%0A%20%20FALSE%20--%3E%20MUTE%5B%22%E5%9B%A2%E9%98%9F%E9%9D%99%E9%9F%B3%E8%AF%A5%E6%B8%A0%E9%81%93%22%5D%0A%20%20Q1%20--%3E%7C%E6%98%AF%7C%20FIX%5B%22%E5%BD%93%E6%89%B9%E4%BF%AE%E5%A4%8D%20%2B%20%E6%B2%89%E6%B7%80%E6%96%AD%E8%A8%80%22%5D%0A%20%20MUTE%20--%3E%20NEXT%5B%22%E4%B8%8B%E6%AC%A1%E7%9C%9F%E9%80%80%E5%8C%96%E6%97%A0%E4%BA%BA%E7%9F%A5%E6%99%93%22%5D%0A%20%20FIX%20--%3E%20HEALTHY%5B%22%E7%9B%91%E6%8E%A7%E5%8F%AF%E4%BF%A1%E5%BA%A6%E4%B8%8A%E5%8D%87%22%5D%0A%20%20HEALTHY%20--%3E%20TUNE%5B%22%E8%AF%AF%E6%8A%A5%E7%8E%87%E5%85%A5%E7%9B%91%E6%8E%A7%EF%BC%9A%E4%BF%AE%E9%98%88%E5%80%BC%E6%88%96%E4%B8%8B%E7%BA%BF%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">常见误区：初学者容易以为断言越多越安全，实际上每条长期误报、无人跟进的断言都在稀释整个告警渠道的可信度——狼来了喊到第三遍，第四遍真狼来了也没人看。所以误报率本身要进监控，连续误报的断言只有两个结局：修阈值，或下线。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>监控不产生正确性：断言只能守住已知的坏形，全新的坏要靠对账与研究异常反推，源头口径见<a href="/quant/data-acquisition-audit">数据获取与审计</a>。阈值维护有真实人力成本，只花在核心表；长尾数据集宁可只留模式层断言，别铺没人维护的假监控。供应商侧的契约与重审义务是质量的另一半，那是下一课供应商对接的对象。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>质量是用途维度的函数：模式、分布、业务、时效四层断言。</li><li>处置三档：阻断、标记、告警，对应错误的可逆性而非严重性。</li><li>阈值相对滚动基线；误报率本身入监控，静音的监控比没有更糟。</li><li>变更触发全量重跑与影子对比，差异超带即停。</li><li>业务层断言把研究教训沉淀为入库闸门，是平台最值钱的一层。</li><li>出处：Wang and Strong, <em>Beyond Accuracy</em>, <em>JMIS</em>, 1996；站内<a href="/quant/data-acquisition-audit">数据获取与审计</a>、<a href="/quant/alt-data-quality">数据质量体系</a>。</li></ul>',5))])}const f=s(F,[["render",u]]);export{g as __pageData,f as default};
